  ('BT3Y-Textual-2hop-Baseline-v0.1', 2, 'Textual 2-hop Baseline v0.1', 'Development Baseline', 'frozen_baseline_with_known_limitations', 'Development evaluation of textual two-hop Agentic RAG over the BT3Y six-report corpus', '{"actual_abstentions":2,"agent_latency_p50_ms":3344.061,"agent_latency_p95_ms":10269.185,"avg_hop_recall":0.479,"avg_iterations":1.333,"avg_tool_calls":2.417,"em":0.25,"f1":0.375,"failed_strategy_count":0,"full_gold_chain_rate":0.125,"gpu_peak_allocated_mib":4590.618,"gpu_peak_reserved_mib":5302.0,"hop_count":2,"machine_facts_calls":0,"numeric_grounding_rate":1.0,"recovered_samples":0,"retrieval_latency_p50_ms":400.977,"retrieval_latency_p95_ms":616.715,"samples":24,"system_errors":0,"tool_result_success_events":58,"trace_complete_rate":1.0}'::jsonb, '9ff4b0d523b9abd613de3f40aecc08e938ee0cdabf83f45b4aa98a7bd8be77a0', 'hopcandy-v0.1-step0-2026-08-12', 'd9a031e88fd177efb2e45e1c9093bd0c4e9a2baabdb8a17c1e4df115de7e3c84', true),
