values
  ('engineering-01', 1, 4, 'E1: isolate independent executor steps', 'The executor appended the first result from a previous step even when comparison branches were independent.', 'Dependency-aware context propagation replaced unconditional result concatenation.', 'F1 rose to 0.349 and average Hop Recall to 0.525 on the 20-question run.', 'Context is useful only when an explicit dependency exists.', 'hopcandy-v0.1-step0-2026-08-12', 'd9a031e88fd177efb2e45e1c9093bd0c4e9a2baabdb8a17c1e4df115de7e3c84', true),
  ('engineering-02', 2, 5, 'E2: force Hybrid RRF for document retrieval', 'Planner-selected retrieval tools produced uneven recall across Chinese, English, and mixed-language reports.', 'Document retrieval steps were routed through keyword and semantic branches with RRF and reranking.', 'Average Hop Recall increased to 0.650 while system errors remained zero.', 'Retrieval policy materially affected evidence coverage before answer generation.', 'hopcandy-v0.1-step0-2026-08-12', 'd9a031e88fd177efb2e45e1c9093bd0c4e9a2baabdb8a17c1e4df115de7e3c84', true),
  ('engineering-03', 3, 8, 'E5: first structured calculation attempt regressed', 'Free-form extraction mixed company, metric, period, value, and unit scopes.', 'The failure was decomposed into slot extraction, grounding, and deterministic calculation contracts.', 'The initial E5 result was preserved as failure evidence rather than relabeled as a pass.', 'Deterministic arithmetic is only reliable after fact selection is reliable.', 'hopcandy-v0.1-step0-2026-08-12', 'd9a031e88fd177efb2e45e1c9093bd0c4e9a2baabdb8a17c1e4df115de7e3c84', true),
  ('engineering-04', 4, 10, 'E5.1B: machine-readable financial facts', 'Table parsing and LLM extraction could not consistently preserve financial scope and units.', 'Machine-readable facts and serialized table evidence were introduced behind validated slots.', 'The original six-document index produced the stronger E5.1B result and was frozen.', 'Structured facts are an Executor tool, not a replacement for Agentic retrieval.', 'hopcandy-v0.1-step0-2026-08-12', 'd9a031e88fd177efb2e45e1c9093bd0c4e9a2baabdb8a17c1e4df115de7e3c84', true),
  ('engineering-05', 5, 22, 'Structured Query Stable v1.0', 'A stable claim required an independent structured test after regression fixes.', 'Structured Test v3 covered direct, entity-dependent, and clarification routes.', '24 fresh samples completed with zero system errors and every structured release gate at 1.0.', 'Structured lookup and multi-fact calculation were frozen as Stable within the declared BT3Y scope.', 'hopcandy-v0.1-step0-2026-08-12', 'd9a031e88fd177efb2e45e1c9093bd0c4e9a2baabdb8a17c1e4df115de7e3c84', true),
  ('engineering-06', 6, 23, 'ISSUE-001: unsupported metric escaped the fast path', 'A carrying-amount question outside Machine Facts returned a wrong value instead of falling back safely.', 'The case became a permanent Safety/Fallback red-test and evidence for non-structured routing work.', 'The failure, expected answer, trace, and remediation boundary were retained in the engineering record.', 'A stable fast path does not imply stable fallback behavior outside its schema.', 'hopcandy-v0.1-step0-2026-08-12', 'd9a031e88fd177efb2e45e1c9093bd0c4e9a2baabdb8a17c1e4df115de7e3c84', true),
  ('engineering-07', 7, 30, 'Dynamic Hop 2 synthesis failed', 'Semantic similarity did not guarantee logical composability, and runtime-generated partner QA had weaker quality controls.', 'The synthesis design moved from dynamic Chunk-to-QA expansion to Seed-to-Seed candidates with Human Gate.', 'Low yield and necessary-hop failures were frozen instead of hidden by looser thresholds.', 'Relation validity is not the same as graph eligibility or necessary-hop quality.', 'hopcandy-v0.1-step0-2026-08-12', 'd9a031e88fd177efb2e45e1c9093bd0c4e9a2baabdb8a17c1e4df115de7e3c84', true),
  ('engineering-08', 8, 107, 'Necessary-hop and multi-positive evidence recovery', 'Pairwise Judge decisions could not independently guarantee graph-level edge quality.', 'A bounded recovery used explicit bridge constraints, deduplication, deterministic merge, and human evidence audit.', 'The candidate-to-edge-to-merge-to-Gold contract closed without reopening unlimited Judge tuning.', 'Human-gated data construction was accepted as an explicit engineering boundary.', 'hopcandy-v0.1-step0-2026-08-12', 'd9a031e88fd177efb2e45e1c9093bd0c4e9a2baabdb8a17c1e4df115de7e3c84', true),
  ('engineering-09', 9, 111, 'Textual 2-hop Baseline v0.1', 'The full-corpus textual system needed an end-to-end result with honest capability boundaries.', 'Development24 ran with Hybrid RRF, reranking, Verifier/Replanner, and Machine Facts disabled for textual questions.', 'EM 0.250, F1 0.375, Hop Recall 0.479, Full Gold Chain 0.125, and zero system errors were frozen.', 'The pipeline is reproducible, but textual two-hop quality remains Development with known limitations.', 'hopcandy-v0.1-step0-2026-08-12', 'd9a031e88fd177efb2e45e1c9093bd0c4e9a2baabdb8a17c1e4df115de7e3c84', true),
  ('engineering-10', 10, 112, 'Qwen3-4B vs Qwen3-8B ablation', 'The 4B baseline could not separate system limitations from model-capacity limitations.', 'The same Development24 and Agent configuration were rerun with Qwen3-8B and controlled output budgets.', '8B raised Hop Recall from 0.479 to 0.688 and Full Gold Chain from 0.125 to 0.500, while increasing latency and tool use.', 'Model scale matters, but it does not replace retrieval and verifier optimization.', 'hopcandy-v0.1-step0-2026-08-12', 'd9a031e88fd177efb2e45e1c9093bd0c4e9a2baabdb8a17c1e4df115de7e3c84', true)
